const cfg = $input.first().json || {};
const CLIENT_ID = '5c32404a-2362-4e33-8236-0231afb0c38d';
const CLIENT_SECRET = '0dfd6095-190c-485e-8e11-45589a4c8499';
const BASE = 'https://api.syncpayments.com.br';
const digits = (v) => String(v == null ? '' : v).replace(/\D/g, '');
const auth = await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/partner/v1/auth-token', headers: { 'Accept': 'application/json' }, body: { client_id: CLIENT_ID, client_secret: CLIENT_SECRET }, json: true });
const tok = auth.access_token;
const amount = Number(cfg.amount) > 0 ? Number(cfg.amount) : 100;
const ci = await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/partner/v1/cash-in', headers: { 'Accept': 'application/json', 'Authorization': 'Bearer ' + tok }, body: { amount, description: cfg.description || 'Sinal de projeto - Ginkgo', client: { name: cfg.name || 'Cliente Ginkgo', cpf: digits(cfg.cpf), email: cfg.email || '', phone: digits(cfg.phone) }, webhook_url: cfg.webhook_url || 'https://example.com/ginkgo-webhook' }, json: true });
return [{ json: { ok: true, pix_code: ci.pix_code, identifier: ci.identifier, amount, message: ci.message } }];

